import pandas as pd
import numpy as np
import itertools

def task_func(data_list=[('a', 1, 2.1), ('b', 2, 3.2), ('c', 3, 4.3), ('d', 4, 5.4), ('e', 5, 6.5)]):
    """
    Calculate the mean of numerical values in each position across tuples in a list.
    Non-numeric values are ignored, and means are computed only from available data.
    """
    if not data_list:
        return pd.DataFrame(columns=['Mean Value'])

    # Determine the maximum length of any tuple to handle varying tuple lengths
    max_len = max(len(t) for t in data_list) if data_list else 0

    if max_len == 0:
        return pd.DataFrame(columns=['Mean Value'])

    # Collect numerical values for each position
    position_values = [[] for _ in range(max_len)]

    for t in data_list:
        for i, val in enumerate(t):
            # Check if the value is numeric (int or float), but not bool
            if isinstance(val, (int, float)) and not isinstance(val, bool):
                position_values[i].append(val)
            # Also handle string representations of numbers? The problem says "Non-numeric values are ignored"
            # Let's try to convert strings to numbers as well
            elif isinstance(val, str):
                try:
                    # Try to convert to float
                    float_val = float(val)
                    position_values[i].append(float_val)
                except (ValueError, TypeError):
                    pass

    # Calculate means
    means = []
    for i in range(max_len):
        if position_values[i]:
            mean_val = np.mean(position_values[i])
        else:
            mean_val = np.nan
        means.append(mean_val)

    # Create DataFrame
    index = [f'Position {i}' for i in range(max_len)]
    df = pd.DataFrame({'Mean Value': means}, index=index)

    return df

